/* Reference SM83 interpreter: one bus access or internal cycle per M-cycle.
 * The opcode switch is generated by gbrecomp --cpu-switch from the
 * instruction templates (gb/recomp/sm83.c). */
#include "cpu_ops.h"

void gb_cpu_interrupt(GbCpu *c, uint16_t vector) {
    c->ime = 0;
    c->halted = 0;
    idle(c);
    idle(c);
    wr(c, --c->sp, (uint8_t)(c->pc >> 8));
    wr(c, --c->sp, (uint8_t)c->pc);
    idle(c);
    c->pc = vector;
}

void gb_cpu_step(GbCpu *c) {
    if (c->halted || c->stopped || c->jammed) {
        idle(c);
        return;
    }
    if (c->ei) {  /* EI: the instruction after it runs before an interrupt can */
        c->ei = 0;
        c->ime = 1;
    }
    switch (rd(c, c->pc++)) {
#include "gb_cpu_switch.inc"
    }
}
